-- ── story 5-5a: contract billing — ad-hoc charges and the minimum monthly charge ──
-- Generated by drizzle-kit (the two tables, the three new columns and the
-- indexes) and hand-amended around the generated part: the fail-fast guard,
-- `IF NOT EXISTS` on every table and index (guide §3), the CHECKs, the
-- charge transition guard, the widened 0062 issue guard, the RLS policies and
-- the post-migration probe (drizzle-kit is blind to CHECKs, triggers and RLS;
-- `bun run db:generate` afterwards reports "No schema changes").
--
--   client_charges          — one ad-hoc charge: one billable event for one
--                             client in one warehouse on one IST day, its
--                             figures fixed at record; pending → approved |
--                             rejected | cancelled, approved → cancelled. An
--                             approved charge bills as its own `adhoc` line
--                             on the invoice of (client, bill_month,
--                             supplier_gstin) — both frozen at record.
--   client_charge_policies  — the tenant's self-approval limit (a missing row
--                             = ₹10,000).
--   client_invoice_lines    — gains `description` and `adhoc_charge_id`; two
--                             new line kinds: `adhoc` / `per_unit` (an
--                             approved charge) and `minimum_adjustment` /
--                             `per_invoice` (the top-up to the card's
--                             minimum monthly charge). The four 0062 line
--                             CHECKs and `priced` are widened (drop and
--                             re-add); the line key gains the charge.
--   rate_card_lines         — gains `minimum_counts`; a fifth code
--                             `minimum_monthly` / `per_month` (₹1 .. ₹1 crore,
--                             at most one per card by the existing unique).
--   client_invoices_guard() — copied from the LIVE definition (0062's — no
--                             later migration replaced it; 0063 and 0098 left
--                             its bytes), with two changes only: the issue
--                             arm's null-card refusal narrows to the four
--                             metered codes, and an issue checks every
--                             `adhoc` line against its approved charge (A8).
--   client_invoice_note_lines (5-6a, 0098) — its two pair CHECKs widened by
--                             their real names (`…_charge_basis`,
--                             `…_uom_basis`), so a credit or debit note can
--                             amend an ad-hoc or minimum line (A3).
--
-- No data: purely additive — every existing row satisfies every widened
-- CHECK by construction (a metered line keeps its arm byte for byte), which
-- the probe proves on the live rows too. Lock cost: the billing tables are
-- small (one line per charge per invoice per month); the re-added CHECKs scan
-- `client_invoice_lines`, `client_invoice_note_lines` and `rate_card_lines`
-- under ACCESS EXCLUSIVE. The deploy migrator's guard
-- (`DEFAULT_LARGE_TABLE_ROWS = 100_000`, `migrate-deploy.ts`) judges the one
-- new unique on `client_invoice_lines`; past that size pre-build
-- `client_invoice_lines_line_key_unique` CONCURRENTLY first (DEPLOY.md §5).
-- The new unique is built BEFORE the old one is dropped (never the same
-- name re-created). Proven by the migration block in
-- `test/client-charges.spec.ts` (applied to a database built from the
-- journal trimmed before it, inside one transaction).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'client_charges'
	) THEN
		RAISE EXCEPTION 'migration 0099: client_charges already exists — this migration has already been applied.';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'client_invoice_notes'
	) THEN
		RAISE EXCEPTION 'migration 0099 is out of order: client_invoice_notes does not exist — 0098 must be applied first.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "client_charge_policies" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"self_approve_limit_paise" bigint NOT NULL,
	"updated_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: A22 — ₹0 .. ₹1 crore.
	CONSTRAINT "client_charge_policies_limit" CHECK ("self_approve_limit_paise" BETWEEN 0 AND 1000000000)
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "client_charges" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"supplier_gstin" text,
	"charge_date" date NOT NULL,
	"bill_month" date NOT NULL,
	"category" text NOT NULL,
	"description" text NOT NULL,
	"sac_code" text NOT NULL,
	"unit" text NOT NULL,
	"quantity_milli" bigint NOT NULL,
	"unit_rate_paise" bigint NOT NULL,
	"amount_paise" bigint NOT NULL,
	"reference" text,
	"client_authorization_ref" text,
	"evidence_note" text,
	"status" text NOT NULL,
	"recorded_by" uuid NOT NULL,
	"recorded_at" timestamp with time zone NOT NULL,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	"decision_note" text,
	"cancelled_by" uuid,
	"cancelled_at" timestamp with time zone,
	"cancel_note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: the charge CHECKs (migration SQL only) ─────────────
	-- The vocabularies mirror `src/modules/billing/client-charges.ts`
	-- (CLIENT_CHARGE_CATEGORIES, SAC_BY_CATEGORY, OTHER_SACS,
	-- CLIENT_CHARGE_UNITS, CLIENT_CHARGE_STATUSES), pinned by
	-- `test/client-charges.spec.ts`.
	CONSTRAINT "client_charges_category" CHECK (
		"category" IN ('extra_labour', 'special_handling', 'returns_processing', 'relabelling', 'repacking', 're_slotting', 'extra_storage', 'other')
	),
	-- Each category fixes its SAC; `other` chooses one of four services SACs.
	CONSTRAINT "client_charges_sac_pair" CHECK (
		("category" IN ('extra_labour', 'special_handling', 'returns_processing') AND "sac_code" = '996719')
		OR ("category" IN ('relabelling', 'repacking') AND "sac_code" = '998540')
		OR ("category" IN ('re_slotting', 'extra_storage') AND "sac_code" = '996729')
		OR ("category" = 'other' AND "sac_code" IN ('996729', '996719', '998540', '998599'))
	),
	CONSTRAINT "client_charges_unit" CHECK (
		"unit" IN ('each', 'hour', 'day', 'carton', 'pallet', 'order', 'shipment', 'container', 'kg', 'lot')
	),
	CONSTRAINT "client_charges_status" CHECK ("status" IN ('pending', 'approved', 'rejected', 'cancelled')),
	-- A29 — every operand bigint (the product ≤ 1e14 never overflows); the
	-- amount is the quantity × rate rounded half up ONCE, ≥ 1 paisa, ≤ ₹1 crore.
	CONSTRAINT "client_charges_figures" CHECK (
		"quantity_milli" BETWEEN 1 AND 10000000
		AND "unit_rate_paise" BETWEEN 1 AND 10000000
		AND "amount_paise" BETWEEN 1 AND 1000000000
		AND "amount_paise" = ("quantity_milli" * "unit_rate_paise" + 500) / 1000
	),
	-- A4 — the first of a month, never before the service month.
	CONSTRAINT "client_charges_bill_month" CHECK (
		extract(day from "bill_month") = 1
		AND "bill_month" >= date_trunc('month', "charge_date")::date
	),
	CONSTRAINT "client_charges_gstin" CHECK (
		"supplier_gstin" IS NULL OR "supplier_gstin" ~ '^[0-9]{2}[A-Z0-9]{13}$'
	),
	-- Each text trimmed and within its length (code points).
	CONSTRAINT "client_charges_text" CHECK (
		"description" = btrim("description") AND char_length("description") BETWEEN 1 AND 200
		AND ("reference" IS NULL OR ("reference" = btrim("reference") AND char_length("reference") BETWEEN 1 AND 100))
		AND ("client_authorization_ref" IS NULL OR ("client_authorization_ref" = btrim("client_authorization_ref") AND char_length("client_authorization_ref") BETWEEN 1 AND 100))
		AND ("evidence_note" IS NULL OR ("evidence_note" = btrim("evidence_note") AND char_length("evidence_note") BETWEEN 1 AND 500))
	),
	-- A2 — the decision stamp: both or neither; never on a pending charge;
	-- always on an approved or rejected one; a rejection says why. A
	-- cancelled charge carries one (approved first) or none (cancelled while
	-- pending).
	CONSTRAINT "client_charges_decided" CHECK (
		("decided_at" IS NULL) = ("decided_by" IS NULL)
		AND ("status" <> 'pending' OR "decided_at" IS NULL)
		AND ("status" NOT IN ('approved', 'rejected') OR "decided_at" IS NOT NULL)
		AND ("status" <> 'rejected' OR "decision_note" IS NOT NULL)
		AND ("decision_note" IS NULL OR char_length(btrim("decision_note")) BETWEEN 1 AND 500)
	),
	-- cancelled ⇔ the cancel stamp ⇔ its actor ⇔ its note (1–500).
	CONSTRAINT "client_charges_cancelled" CHECK (
		("status" = 'cancelled') = ("cancelled_at" IS NOT NULL)
		AND ("cancelled_at" IS NULL) = ("cancelled_by" IS NULL)
		AND ("cancelled_at" IS NULL) = ("cancel_note" IS NULL)
		AND ("cancel_note" IS NULL OR char_length(btrim("cancel_note")) BETWEEN 1 AND 500)
	)
);
