-- ── hand-amended: the charge transition guard ─────────────────────────
-- An INSERT is born `pending` with no decision stamp, or `approved` at
-- record by its own recorder (A22's self-approval), never into an invoiced
-- billing month. An UPDATE makes only the
-- A14 transitions — pending → approved (a SECOND person: decided_by ≠
-- recorded_by), pending → rejected, pending → cancelled (no decision stamp),
-- approved → cancelled (refused while an ad-hoc line of this charge sits on
-- an issued, disputed or settled invoice — A8) — and none of them while the
-- charge's billing month is invoiced under its GSTIN. A set decision stamp
-- never changes; every other column is frozen (compared as jsonb, so a later
-- column is frozen too). A charge is never deleted.
CREATE FUNCTION "client_charges_guard"() RETURNS trigger LANGUAGE plpgsql VOLATILE AS $$
DECLARE
	mutable text[] := ARRAY['status', 'decided_by', 'decided_at', 'decision_note', 'cancelled_by', 'cancelled_at', 'cancel_note', 'updated_at'];
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'client_charges: a charge is never deleted (charge %) — cancel it', OLD."id";
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NOT ((NEW."status" = 'pending' AND NEW."decided_at" IS NULL)
			OR (NEW."status" = 'approved' AND NEW."decided_at" IS NOT NULL AND NEW."decided_by" = NEW."recorded_by")) THEN
			RAISE EXCEPTION 'client_charges: a charge is born pending, or approved by its own recorder (charge %)', NEW."id";
		END IF;
		-- A4 (code review C8) — a charge is never born into an invoiced month.
		IF EXISTS (
			SELECT 1 FROM "client_invoices" i
			WHERE i."tenant_id" = NEW."tenant_id" AND i."client_id" = NEW."client_id"
				AND i."period_start" = NEW."bill_month"
				AND coalesce(i."supplier_gstin", '') = coalesce(NEW."supplier_gstin", '')
				AND i."status" IN ('issued', 'disputed', 'settled')
		) THEN
			RAISE EXCEPTION 'client_charges: charge % is born into a billing month already invoiced — bill it on the next open month', NEW."id";
		END IF;
		RETURN NEW;
	END IF;
	IF (to_jsonb(NEW) - mutable) IS DISTINCT FROM (to_jsonb(OLD) - mutable) THEN
		RAISE EXCEPTION 'client_charges: charge % never changes — cancel it and record it again', OLD."id";
	END IF;
	IF OLD."decided_at" IS NOT NULL AND (
		NEW."decided_at" IS DISTINCT FROM OLD."decided_at"
		OR NEW."decided_by" IS DISTINCT FROM OLD."decided_by"
		OR NEW."decision_note" IS DISTINCT FROM OLD."decision_note"
	) THEN
		RAISE EXCEPTION 'client_charges: the decision on charge % never changes', OLD."id";
	END IF;
	IF NOT (
		(OLD."status" = 'pending' AND NEW."status" IN ('approved', 'rejected', 'cancelled'))
		OR (OLD."status" = 'approved' AND NEW."status" = 'cancelled')
	) THEN
		RAISE EXCEPTION 'client_charges: charge % — % → % is not a transition', OLD."id", OLD."status", NEW."status";
	END IF;
	IF OLD."status" = 'pending' AND NEW."status" = 'approved' AND NEW."decided_by" = NEW."recorded_by" THEN
		RAISE EXCEPTION 'client_charges: charge % needs a second approver — its recorder cannot approve it', OLD."id";
	END IF;
	IF OLD."status" = 'pending' AND NEW."status" = 'cancelled' AND NEW."decided_at" IS NOT NULL THEN
		RAISE EXCEPTION 'client_charges: a pending charge is cancelled without a decision (charge %)', OLD."id";
	END IF;
	IF OLD."status" = 'approved' AND EXISTS (
		SELECT 1 FROM "client_invoice_lines" l
		JOIN "client_invoices" i ON i."id" = l."invoice_id"
		WHERE l."tenant_id" = OLD."tenant_id" AND l."adhoc_charge_id" = OLD."id"
			AND i."status" IN ('issued', 'disputed', 'settled')
	) THEN
		RAISE EXCEPTION 'client_charges: charge % is billed on an issued invoice — it can no longer be cancelled', OLD."id";
	END IF;
	IF EXISTS (
		SELECT 1 FROM "client_invoices" i
		WHERE i."tenant_id" = OLD."tenant_id" AND i."client_id" = OLD."client_id"
			AND i."period_start" = OLD."bill_month"
			AND coalesce(i."supplier_gstin", '') = coalesce(OLD."supplier_gstin", '')
			AND i."status" IN ('issued', 'disputed', 'settled')
	) THEN
		RAISE EXCEPTION 'client_charges: the billing month of charge % is invoiced — it can no longer change', OLD."id";
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_charges_frozen" BEFORE INSERT OR UPDATE OR DELETE ON "client_charges"
	FOR EACH ROW EXECUTE FUNCTION "client_charges_guard"();--> statement-breakpoint
CREATE FUNCTION "client_charges_refuse_truncate"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	RAISE EXCEPTION '% is never truncated: a recorded charge is billing history', TG_TABLE_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_charges_no_truncate" BEFORE TRUNCATE ON "client_charges"
	FOR EACH STATEMENT EXECUTE FUNCTION "client_charges_refuse_truncate"();--> statement-breakpoint
CREATE TRIGGER "client_charge_policies_no_truncate" BEFORE TRUNCATE ON "client_charge_policies"
	FOR EACH STATEMENT EXECUTE FUNCTION "client_charges_refuse_truncate"();--> statement-breakpoint
-- ── hand-amended: the issue guard (A8, A9, A17) ───────────────────────
-- Copied from the LIVE `client_invoices_guard()` — 0062's body (0063 and
-- 0098 left it untouched). The ONLY differences: (1) the unpriced refusal's
-- null-card arm reads `l."charge_code" IN (the four metered codes) AND
-- l."rate_card_id" IS NULL` (an ad-hoc line and the minimum adjustment
-- carry no card by construction); (2) an issue refuses an `adhoc` line whose
-- charge is not approved for THIS invoice — its tenant, the invoice's
-- client, `bill_month = period_start`, the invoice's supplying GSTIN — or
-- whose charge sits on another non-void invoice. Both arms are reachable
-- only through `adhoc` lines, so every existing invoice issues exactly as
-- before. `test/client-charges.spec.ts` diffs the pre-migration body
-- against this one.
CREATE OR REPLACE FUNCTION "client_invoices_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
	frozen text[] := ARRAY['status', 'status_note', 'status_changed_at', 'status_changed_by', 'updated_at'];
	line_count bigint;
	sum_amount bigint;
	sum_cgst bigint;
	sum_sgst bigint;
	sum_igst bigint;
BEGIN
	IF TG_OP = 'DELETE' THEN
		IF OLD."status" <> 'draft' THEN
			RAISE EXCEPTION 'client_invoices: a % invoice is never deleted (invoice %)', OLD."status", OLD."id";
		END IF;
		IF EXISTS (SELECT 1 FROM "client_invoice_lines" WHERE "invoice_id" = OLD."id") THEN
			RAISE EXCEPTION 'client_invoices: draft % still has lines — delete its lines first', OLD."id";
		END IF;
		RETURN OLD;
	END IF;
	IF NEW."id" IS DISTINCT FROM OLD."id"
		OR NEW."tenant_id" IS DISTINCT FROM OLD."tenant_id"
		OR NEW."client_id" IS DISTINCT FROM OLD."client_id"
		OR NEW."period_start" IS DISTINCT FROM OLD."period_start"
		OR NEW."period_end" IS DISTINCT FROM OLD."period_end"
		OR NEW."supplier_gstin" IS DISTINCT FROM OLD."supplier_gstin"
		OR NEW."replaces_invoice_id" IS DISTINCT FROM OLD."replaces_invoice_id"
		OR NEW."created_by" IS DISTINCT FROM OLD."created_by"
		OR NEW."created_at" IS DISTINCT FROM OLD."created_at" THEN
		RAISE EXCEPTION 'client_invoices: the identity of invoice % never changes', OLD."id";
	END IF;
	IF OLD."status" = 'draft' THEN
		IF NEW."status" = 'draft' THEN
			RETURN NEW;
		END IF;
		IF NEW."status" <> 'issued' THEN
			RAISE EXCEPTION 'client_invoices: a draft is issued or discarded — draft → % refused (invoice %)', NEW."status", OLD."id";
		END IF;
		IF NEW."invoice_no" IS NULL OR NEW."supplier_gstin" IS NULL OR NEW."issued_at" IS NULL THEN
			RAISE EXCEPTION 'client_invoices: invoice % cannot issue without its number, supplying GSTIN and issue stamp', OLD."id";
		END IF;
		IF EXISTS (
			SELECT 1 FROM "client_invoice_lines" l
			WHERE l."invoice_id" = OLD."id"
				AND ((l."charge_code" IN ('storage', 'inbound_handling', 'pick', 'outbound_handling') AND l."rate_card_id" IS NULL)
					OR l."unit_amount_paise" IS NULL OR l."amount_paise" IS NULL
					OR l."place_of_supply" IS NULL OR l."supply_type" IS NULL)
		) THEN
			RAISE EXCEPTION 'client_invoices: invoice % has an unpriced line (or one with no place of supply) — it cannot issue', OLD."id";
		END IF;
		-- Story 5-5a (A8) — every ad-hoc line bills an APPROVED charge of this
		-- client, for this invoice's month and supplying GSTIN, on no other
		-- live invoice.
		IF EXISTS (
			SELECT 1 FROM "client_invoice_lines" l
			WHERE l."invoice_id" = OLD."id" AND l."charge_code" = 'adhoc'
				AND NOT EXISTS (
					SELECT 1 FROM "client_charges" c
					WHERE c."id" = l."adhoc_charge_id" AND c."tenant_id" = l."tenant_id"
						AND c."client_id" = NEW."client_id" AND c."status" = 'approved'
						AND c."bill_month" = NEW."period_start"
						AND c."supplier_gstin" IS NOT DISTINCT FROM NEW."supplier_gstin"
				)
		) THEN
			RAISE EXCEPTION 'client_invoices: invoice % has an ad-hoc line whose charge is not approved for this client, month and GSTIN — it cannot issue', OLD."id";
		END IF;
		IF EXISTS (
			SELECT 1 FROM "client_invoice_lines" l
			JOIN "client_invoice_lines" o ON o."adhoc_charge_id" = l."adhoc_charge_id" AND o."invoice_id" <> l."invoice_id"
			JOIN "client_invoices" oi ON oi."id" = o."invoice_id" AND oi."status" <> 'void'
			WHERE l."invoice_id" = OLD."id" AND l."charge_code" = 'adhoc'
		) THEN
			RAISE EXCEPTION 'client_invoices: invoice % bills an ad-hoc charge another live invoice already bills — it cannot issue', OLD."id";
		END IF;
		-- … and no charge of this client, month and GSTIN still awaits a
		-- decision (the `adhoc-charge-pending` gap's backstop — code review C8).
		IF EXISTS (
			SELECT 1 FROM "client_charges" c
			WHERE c."tenant_id" = NEW."tenant_id" AND c."client_id" = NEW."client_id"
				AND c."bill_month" = NEW."period_start" AND c."status" = 'pending'
				AND c."supplier_gstin" IS NOT DISTINCT FROM NEW."supplier_gstin"
		) THEN
			RAISE EXCEPTION 'client_invoices: invoice % has a pending ad-hoc charge for its month — approve or reject it first', OLD."id";
		END IF;
		-- An issued document has lines, and its header is THEIR sums — a
		-- header written without its lines (or out of step with them) never
		-- becomes a tax invoice. And it prints a real party.
		SELECT count(*), coalesce(sum(l."amount_paise"), 0), coalesce(sum(l."cgst_paise"), 0),
				coalesce(sum(l."sgst_paise"), 0), coalesce(sum(l."igst_paise"), 0)
			INTO line_count, sum_amount, sum_cgst, sum_sgst, sum_igst
			FROM "client_invoice_lines" l WHERE l."invoice_id" = OLD."id";
		IF line_count = 0 THEN
			RAISE EXCEPTION 'client_invoices: invoice % has no line — it cannot issue', OLD."id";
		END IF;
		IF NEW."subtotal_paise" <> sum_amount OR NEW."cgst_paise" <> sum_cgst
			OR NEW."sgst_paise" <> sum_sgst OR NEW."igst_paise" <> sum_igst THEN
			RAISE EXCEPTION 'client_invoices: invoice % header totals are not the sums of its lines — it cannot issue', OLD."id";
		END IF;
		IF NEW."party" = '{}'::jsonb THEN
			RAISE EXCEPTION 'client_invoices: invoice % has no party to print — it cannot issue', OLD."id";
		END IF;
		RETURN NEW;
	END IF;
	-- Non-draft.
	IF NOT (
		(OLD."status" = 'issued' AND NEW."status" IN ('disputed', 'settled', 'void'))
		OR (OLD."status" = 'disputed' AND NEW."status" IN ('settled', 'void'))
	) THEN
		RAISE EXCEPTION 'client_invoices: invoice % is frozen — % → % is not a transition', OLD."id", OLD."status", NEW."status";
	END IF;
	IF NEW."status" IN ('disputed', 'void') AND NEW."status_note" IS NULL THEN
		RAISE EXCEPTION 'client_invoices: % needs a note (invoice %)', NEW."status", OLD."id";
	END IF;
	IF NEW."status_changed_at" IS NULL OR NEW."status_changed_at" IS NOT DISTINCT FROM OLD."status_changed_at" THEN
		RAISE EXCEPTION 'client_invoices: a transition stamps status_changed_at (invoice %)', OLD."id";
	END IF;
	IF (to_jsonb(NEW) - frozen) IS DISTINCT FROM (to_jsonb(OLD) - frozen) THEN
		RAISE EXCEPTION 'client_invoices: invoice % is frozen after issue — only its status, note and stamps change', OLD."id";
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
-- ── hand-amended: RLS (A7) — both tables OPERATOR-ONLY ────────────────
-- One FOR ALL policy each in the `client_invoice_series` shape (0062): the
-- tenant AND `app.client_id` unset. A portal session reads no charge and
-- writes none (charges reach the portal only as frozen invoice lines).
ALTER TABLE "client_charges" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "client_charge_policies" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "client_charges_tenant_isolation" ON "client_charges"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND NULLIF(current_setting('app.client_id', true), '') IS NULL
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND NULLIF(current_setting('app.client_id', true), '') IS NULL
	);--> statement-breakpoint
CREATE POLICY "client_charge_policies_tenant_isolation" ON "client_charge_policies"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND NULLIF(current_setting('app.client_id', true), '') IS NULL
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND NULLIF(current_setting('app.client_id', true), '') IS NULL
	);--> statement-breakpoint
-- ── the post-migration assertion (the 0064 / 0098 model) ─────────────────
-- What landed: RLS and the two policies, the three triggers, the new line
-- key and the policy unique (`to_regclass`), the old line key gone, the
-- issue guard's new arms (`prosrc`). Then, on made-up uuids inside one
-- subtransaction rolled back by a sentinel: the ACCEPTED shapes — a pending
-- charge approved by a second person, one rejected, one cancelled while
-- pending, one approved at record and cancelled, the largest figures under
-- the cap, an issued invoice carrying an ad-hoc line and a minimum
-- adjustment beside a metered line, a credit note amending the ad-hoc line,
-- a minimum-only card line, a policy row — then the trigger refusals (P0001,
-- each matched on its message), then, with the row triggers DISABLED
-- (inside the same rolled-back subtransaction), every new or widened CHECK
-- and unique refused by its own name. Last, every live row satisfies the
-- widened CHECKs (they were re-added validated).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	u1 uuid := gen_random_uuid();
	u2 uuid := gen_random_uuid();
	card uuid := gen_random_uuid();
	inv uuid := gen_random_uuid();
	inv2 uuid := gen_random_uuid();
	ch1 uuid := gen_random_uuid();
	ch2 uuid := gen_random_uuid();
	ch3 uuid := gen_random_uuid();
	ch4 uuid := gen_random_uuid();
	ch5 uuid := gen_random_uuid();
	ch6 uuid := gen_random_uuid();
	ch7 uuid := gen_random_uuid();
	inv_dec uuid := gen_random_uuid();
	inv_jan uuid := gen_random_uuid();
	inv_feb uuid := gen_random_uuid();
	l_meter uuid := gen_random_uuid();
	l_adhoc uuid := gen_random_uuid();
	l_min uuid := gen_random_uuid();
	note1 uuid := gen_random_uuid();
	g text := '29AAACT1234A1Z5';
	pty jsonb := '{"probe": true}'::jsonb;
	month_from timestamptz := '2026-09-30T18:30:00Z';
	month_to timestamptz := '2026-10-31T18:30:00Z';
	day_from timestamptz := '2026-10-04T18:30:00Z';
	day_to timestamptz := '2026-10-05T18:30:00Z';
	refused_by text;
	refused_message text;
	expected text;
	probe text;
	guard_src text;
BEGIN
	IF (SELECT count(*) FROM pg_class WHERE relname IN ('client_charges', 'client_charge_policies') AND relrowsecurity) <> 2 THEN
		RAISE EXCEPTION 'migration 0099: RLS is not enabled on both charge tables.';
	END IF;
	IF (SELECT count(*) FROM pg_policies
		WHERE schemaname = current_schema() AND tablename IN ('client_charges', 'client_charge_policies')) <> 2 THEN
		RAISE EXCEPTION 'migration 0099: expected one policy on each charge table.';
	END IF;
	IF (SELECT count(*) FROM pg_trigger
		WHERE NOT tgisinternal AND tgname IN ('client_charges_frozen', 'client_charges_no_truncate', 'client_charge_policies_no_truncate')) <> 3 THEN
		RAISE EXCEPTION 'migration 0099: expected the three charge triggers.';
	END IF;
	IF to_regclass('public.client_invoice_lines_line_key_unique') IS NULL
		OR to_regclass('public.client_charge_policies_tenant_unique') IS NULL THEN
		RAISE EXCEPTION 'migration 0099: a new unique is missing.';
	END IF;
	IF to_regclass('public.client_invoice_lines_invoice_segment_charge_uom_unique') IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0099: the 21-5 line key was not dropped.';
	END IF;
	SELECT p.prosrc INTO guard_src FROM pg_proc p WHERE p.proname = 'client_invoices_guard';
	IF position('l."charge_code" IN (''storage'', ''inbound_handling'', ''pick'', ''outbound_handling'') AND l."rate_card_id" IS NULL' IN guard_src) = 0
		OR position('c."bill_month" = NEW."period_start"' IN guard_src) = 0
		OR position('c."status" = ''approved''' IN guard_src) = 0
		OR position('oi."status" <> ''void''' IN guard_src) = 0 THEN
		RAISE EXCEPTION 'migration 0099: client_invoices_guard does not carry the metered-codes predicate and the ad-hoc checks.';
	END IF;

	-- ── A29: a charge that rounds to zero paise (0.001 × 1 paisa) is refused
	-- by `client_charges_figures` — never written as a ₹0 line.
	BEGIN
		INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
				"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at")
			VALUES (gen_random_uuid(), t, c, w, g, '2026-10-05', '2026-10-01', 'other', 'Rounds to nothing', '998599', 'each', 1, 1, 0, 'pending', u1, now());
		RAISE EXCEPTION USING ERRCODE = 'P0099', MESSAGE = 'admitted';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'client_charges_figures' THEN
				RAISE EXCEPTION 'migration 0099: the rounds-to-zero charge was refused by % (expected client_charges_figures).', coalesce(refused_by, 'nothing');
			END IF;
		WHEN SQLSTATE 'P0099' THEN
			RAISE EXCEPTION 'migration 0099: a charge that rounds to zero paise was admitted.';
	END;

	BEGIN
		INSERT INTO "rate_cards" ("id","tenant_id","client_id","status","created_by") VALUES (card, t, c, 'draft', u1);
		INSERT INTO "rate_card_lines" ("id","tenant_id","client_id","rate_card_id","charge_code","basis","amount_paise","minimum_counts")
			VALUES (gen_random_uuid(), t, c, card, 'minimum_monthly', 'per_month', 1000000000, 'metered');
		INSERT INTO "rate_card_lines" ("id","tenant_id","client_id","rate_card_id","charge_code","basis","amount_paise")
			VALUES (gen_random_uuid(), t, c, card, 'pick', 'per_pick', 10000000);
		INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
				"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at")
			VALUES
				(ch1, t, c, w, g, '2026-10-05', '2026-10-01', 'extra_labour', 'Unloading a 40-ft container', '996719', 'hour', 2500, 35000, 87500, 'pending', u1, now()),
				(ch2, t, c, w, g, '2026-10-05', '2026-10-01', 'relabelling', 'Relabel 120 cartons', '998540', 'carton', 120000, 1500, 180000, 'pending', u1, now()),
				(ch3, t, c, w, NULL, '2026-09-20', '2026-10-01', 'other', 'Pallet wrap', '998599', 'pallet', 1000, 1, 1, 'pending', u1, now()),
				(ch5, t, c, w, g, '2026-10-06', '2026-12-01', 're_slotting', 'Re-slot the fast movers', '996729', 'lot', 10000000, 100000, 1000000000, 'pending', u1, now());
		INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
				"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","reference","client_authorization_ref","evidence_note",
				"status","recorded_by","recorded_at","decided_by","decided_at")
			VALUES
				(ch4, t, c, w, g, '2026-10-05', '2026-10-01', 'repacking', 'Repack', '998540', 'each', 1000, 100, 100, 'GRN-1', 'PO 7781', 'photos on file',
					'approved', u1, now(), u1, now()),
				(ch6, t, c, w, g, '2026-10-05', '2026-10-01', 'extra_storage', 'Overflow space', '996729', 'day', 2000, 2500, 5000, NULL, NULL, NULL,
					'approved', u1, now(), u1, now());
		UPDATE "client_charges" SET "status" = 'approved', "decided_by" = u2, "decided_at" = now() WHERE "id" = ch1;
		UPDATE "client_charges" SET "status" = 'rejected', "decided_by" = u2, "decided_at" = now(), "decision_note" = 'not agreed' WHERE "id" = ch2;
		UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u1, "cancelled_at" = now(), "cancel_note" = 'entered twice' WHERE "id" = ch3;
		UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u2, "cancelled_at" = now(), "cancel_note" = 'wrong client' WHERE "id" = ch4;
		INSERT INTO "client_charge_policies" ("id","tenant_id","self_approve_limit_paise","updated_by") VALUES (gen_random_uuid(), t, 1000000000, u1);

		-- ── an October invoice: one metered pick line, the ad-hoc line of ch6
		-- (2 days × ₹25.00 = ₹50.00) and a minimum adjustment of ₹9.50;
		-- intra-state, issued.
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv, t, c, '2026-10-01', '2026-10-31', 'draft', g, '29', 'intra', 7000, 629, 631, 0, 1260, 8260, 40, 8300,
				'[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise",
				"description","adhoc_charge_id")
			VALUES
				(l_meter, t, inv, card, month_from, month_to, 'pick', 'per_pick', NULL, 1, 1050, 1050, '996719', 1800, '29', 'intra', 94, 95, 0, NULL, NULL),
				(l_adhoc, t, inv, NULL, day_from, day_to, 'adhoc', 'per_unit', 'day', 2000, 2500, 5000, '996729', 1800, '29', 'intra', 450, 450, 0,
					'Extra storage — Overflow space', ch6),
				(l_min, t, inv, NULL, month_from, month_to, 'minimum_adjustment', 'per_invoice', NULL, 1, 950, 950, '996729', 1800, '29', 'intra', 85, 86, 0,
					'Minimum monthly charge ₹70.00 less metered charges ₹60.50', NULL);
		UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000001', "fy_label" = 'FY-2627', "series_seq" = 1,
				"issued_at" = now(), "issued_by" = u1
			WHERE "id" = inv;
		-- A credit note amends the ad-hoc line (5-6a's widened pair CHECKs).
		INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
				"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (note1, t, c, inv, 'credit', g, '29', 'intra', 'excess-billed', 'probe', 1000, 90, 90, 0, 180, 1180, 0, 1180, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
				"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
			VALUES (gen_random_uuid(), t, note1, l_adhoc, 'adhoc', 'per_unit', 'day', day_from, day_to, '996729', 1800, '29', 'intra', 1000, 90, 90, 0);
		-- A second (draft) invoice of another month for the guard's refusals.
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv2, t, c, '2026-11-01', '2026-11-30', 'draft', g, '29', 'intra', 87500, 7875, 7875, 0, 15750, 103250, 50, 103300,
				'[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise",
				"description","adhoc_charge_id")
			VALUES (gen_random_uuid(), t, inv2, NULL, day_from, day_to, 'adhoc', 'per_unit', 'hour', 2500, 35000, 87500, '996719', 1800, '29', 'intra', 7875, 7875, 0,
				'Extra labour — Unloading a 40-ft container', ch1);

		-- December: a draft with a metered line while ch5 (Dec) is pending.
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv_dec, t, c, '2026-12-01', '2026-12-31', 'draft', g, '29', 'intra', 1050, 94, 95, 0, 189, 1239, -39, 1200,
				'[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise")
			VALUES (gen_random_uuid(), t, inv_dec, card, '2026-11-30T18:30:00Z', '2026-12-31T18:30:00Z', 'pick', 'per_pick', NULL, 1, 1050, 1050, '996719', 1800, '29', 'intra', 94, 95, 0);
		-- January and February drafts that BOTH bill ch7 (approved, January).
		INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
				"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at","decided_by","decided_at")
			VALUES (ch7, t, c, w, g, '2027-01-05', '2027-01-01', 'extra_storage', 'Overflow space', '996729', 'day', 2000, 2500, 5000, 'approved', u1, now(), u1, now());
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv_jan, t, c, '2027-01-01', '2027-01-31', 'draft', g, '29', 'intra', 5000, 450, 450, 0, 900, 5900, 0, 5900, '[]'::jsonb, '[]'::jsonb, pty, 'probe', u1),
				(inv_feb, t, c, '2027-02-01', '2027-02-28', 'draft', g, '29', 'intra', 5000, 450, 450, 0, 900, 5900, 0, 5900, '[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise",
				"description","adhoc_charge_id")
			VALUES (gen_random_uuid(), t, inv_jan, NULL, '2027-01-04T18:30:00Z', '2027-01-05T18:30:00Z', 'adhoc', 'per_unit', 'day', 2000, 2500, 5000, '996729', 1800, '29', 'intra', 450, 450, 0,
					'Extra storage — Overflow space', ch7),
				(gen_random_uuid(), t, inv_feb, NULL, '2027-01-04T18:30:00Z', '2027-01-05T18:30:00Z', 'adhoc', 'per_unit', 'day', 2000, 2500, 5000, '996729', 1800, '29', 'intra', 450, 450, 0,
					'Extra storage — Overflow space', ch7);

		-- ── the trigger refusals (P0001), each matched on its message.
		FOREACH probe IN ARRAY ARRAY[
			'insert into an invoiced month',
			'issue with a pending charge',
			'issue a charge another live invoice bills',
			'insert approved by another',
			'insert rejected',
			'approve own pending',
			'edit a figure',
			'change the decision',
			'rejected to approved',
			'cancelled to approved',
			'cancel pending with a decision',
			'delete a charge',
			'cancel a billed charge',
			'cancel in an invoiced month',
			'issue an ad-hoc line of another month',
			'truncate the charges'
		] LOOP
			refused_by := NULL;
			refused_message := NULL;
			expected := CASE probe
				WHEN 'insert into an invoiced month' THEN '%born into a billing month already invoiced%'
				WHEN 'issue with a pending charge' THEN '%pending ad-hoc charge%'
				WHEN 'issue a charge another live invoice bills' THEN '%another live invoice already bills%'
				WHEN 'insert approved by another' THEN '%born pending%'
				WHEN 'insert rejected' THEN '%born pending%'
				WHEN 'approve own pending' THEN '%needs a second approver%'
				WHEN 'edit a figure' THEN '%never changes%'
				WHEN 'change the decision' THEN '%decision on charge%never changes%'
				WHEN 'rejected to approved' THEN '%is not a transition%'
				WHEN 'cancelled to approved' THEN '%is not a transition%'
				WHEN 'cancel pending with a decision' THEN '%without a decision%'
				WHEN 'delete a charge' THEN '%never deleted%'
				WHEN 'cancel a billed charge' THEN '%billed on an issued invoice%'
				WHEN 'cancel in an invoiced month' THEN '%billing month%is invoiced%'
				WHEN 'issue an ad-hoc line of another month' THEN '%not approved for this client, month and GSTIN%'
				ELSE '%never truncated%'
			END;
			BEGIN
				CASE probe
					WHEN 'insert into an invoiced month' THEN
						INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
								"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at")
							VALUES (gen_random_uuid(), t, c, w, g, '2026-10-07', '2026-10-01', 'repacking', 'Repack', '998540', 'each', 1000, 100, 100, 'pending', u1, now());
					WHEN 'issue with a pending charge' THEN
						UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000003', "fy_label" = 'FY-2627', "series_seq" = 3,
								"issued_at" = now(), "issued_by" = u1
							WHERE "id" = inv_dec;
					WHEN 'issue a charge another live invoice bills' THEN
						UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000004', "fy_label" = 'FY-2627', "series_seq" = 4,
								"issued_at" = now(), "issued_by" = u1
							WHERE "id" = inv_jan;
					WHEN 'insert approved by another' THEN
						INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
								"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at","decided_by","decided_at")
							VALUES (gen_random_uuid(), t, c, w, g, '2026-10-05', '2026-11-01', 'repacking', 'Repack', '998540', 'each', 1000, 100, 100,
								'approved', u1, now(), u2, now());
					WHEN 'insert rejected' THEN
						INSERT INTO "client_charges" ("id","tenant_id","client_id","warehouse_id","supplier_gstin","charge_date","bill_month","category","description",
								"sac_code","unit","quantity_milli","unit_rate_paise","amount_paise","status","recorded_by","recorded_at","decided_by","decided_at","decision_note")
							VALUES (gen_random_uuid(), t, c, w, g, '2026-10-05', '2026-11-01', 'repacking', 'Repack', '998540', 'each', 1000, 100, 100,
								'rejected', u1, now(), u2, now(), 'no');
					WHEN 'approve own pending' THEN
						UPDATE "client_charges" SET "status" = 'approved', "decided_by" = u1, "decided_at" = now() WHERE "id" = ch5;
					WHEN 'edit a figure' THEN
						UPDATE "client_charges" SET "amount_paise" = 999999999, "unit_rate_paise" = 9999999 WHERE "id" = ch5;
					WHEN 'change the decision' THEN
						UPDATE "client_charges" SET "decision_note" = 'rewritten' WHERE "id" = ch2;
					WHEN 'rejected to approved' THEN
						UPDATE "client_charges" SET "status" = 'approved' WHERE "id" = ch2;
					WHEN 'cancelled to approved' THEN
						UPDATE "client_charges" SET "status" = 'approved', "cancelled_by" = NULL, "cancelled_at" = NULL, "cancel_note" = NULL,
								"decided_by" = u2, "decided_at" = now()
							WHERE "id" = ch3;
					WHEN 'cancel pending with a decision' THEN
						UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u1, "cancelled_at" = now(), "cancel_note" = 'x',
								"decided_by" = u2, "decided_at" = now()
							WHERE "id" = ch5;
					WHEN 'delete a charge' THEN
						DELETE FROM "client_charges" WHERE "id" = ch5;
					WHEN 'cancel a billed charge' THEN
						UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u2, "cancelled_at" = now(), "cancel_note" = 'x' WHERE "id" = ch6;
					WHEN 'cancel in an invoiced month' THEN
						-- ch1: approved for October, billed only on a DRAFT (November) — the billed arm passes, the month arm refuses.
						UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u2, "cancelled_at" = now(), "cancel_note" = 'x' WHERE "id" = ch1;
					WHEN 'issue an ad-hoc line of another month' THEN
						UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000002', "fy_label" = 'FY-2627', "series_seq" = 2,
								"issued_at" = now(), "issued_by" = u1
							WHERE "id" = inv2;
					WHEN 'truncate the charges' THEN
						TRUNCATE "client_charges";
				END CASE;
			EXCEPTION
				WHEN raise_exception THEN
					GET STACKED DIAGNOSTICS refused_message = MESSAGE_TEXT;
					refused_by := 'P0001';
			END;
			IF refused_by IS NULL OR refused_message NOT LIKE expected THEN
				RAISE EXCEPTION 'migration 0099: trigger probe "%" was not refused as expected (got %).', probe, coalesce(refused_message, 'no refusal');
			END IF;
		END LOOP;

		-- ── the CHECK and unique probes: the row triggers off (rolled back
		-- with this subtransaction), each refused by its own name.
		ALTER TABLE "client_charges" DISABLE TRIGGER "client_charges_frozen";
		ALTER TABLE "client_invoice_lines" DISABLE TRIGGER "client_invoice_lines_frozen";
		ALTER TABLE "rate_card_lines" DISABLE TRIGGER "rate_card_lines_frozen";
		ALTER TABLE "client_invoice_note_lines" DISABLE TRIGGER "client_invoice_note_lines_frozen";
		FOREACH probe IN ARRAY ARRAY[
			'unknown category',
			'labour on the packing SAC',
			'other on a goods SAC',
			'unknown unit',
			'unknown status',
			'quantity zero',
			'rate over the cap',
			'amount over the cap',
			'amount not the rounded product',
			'bill month not a first',
			'bill month before the service month',
			'malformed gstin',
			'untrimmed description',
			'description of 201',
			'reference of 101',
			'blank evidence',
			'pending with a decision',
			'approved without a decision',
			'rejected without a note',
			'cancelled without a note',
			'stamp without its actor',
			'policy over the cap',
			'policy twice',
			'unknown line code',
			'unknown line basis',
			'ad-hoc on the wrong basis',
			'ad-hoc without a unit',
			'ad-hoc with a card',
			'ad-hoc with no rate',
			'ad-hoc amount not the rounded product',
			'adjustment with a card',
			'adjustment amount not its unit',
			'adjustment over the cap',
			'adjustment of two',
			'ad-hoc without its charge',
			'metered line with a description',
			'metered line with a charge',
			'adjustment without a description',
			'the same charge twice on an invoice',
			'metered rate over 1 lakh',
			'minimum of zero',
			'minimum over 1 crore',
			'minimum on the wrong basis',
			'minimum without its counts',
			'counts on a metered line',
			'unknown counts',
			'note line ad-hoc on the wrong basis',
			'note line ad-hoc without a unit'
		] LOOP
			refused_by := NULL;
			expected := CASE probe
				WHEN 'unknown category' THEN 'client_charges_category'
				WHEN 'labour on the packing SAC' THEN 'client_charges_sac_pair'
				WHEN 'other on a goods SAC' THEN 'client_charges_sac_pair'
				WHEN 'unknown unit' THEN 'client_charges_unit'
				WHEN 'unknown status' THEN 'client_charges_status'
				WHEN 'quantity zero' THEN 'client_charges_figures'
				WHEN 'rate over the cap' THEN 'client_charges_figures'
				WHEN 'amount over the cap' THEN 'client_charges_figures'
				WHEN 'amount not the rounded product' THEN 'client_charges_figures'
				WHEN 'bill month not a first' THEN 'client_charges_bill_month'
				WHEN 'bill month before the service month' THEN 'client_charges_bill_month'
				WHEN 'malformed gstin' THEN 'client_charges_gstin'
				WHEN 'untrimmed description' THEN 'client_charges_text'
				WHEN 'description of 201' THEN 'client_charges_text'
				WHEN 'reference of 101' THEN 'client_charges_text'
				WHEN 'blank evidence' THEN 'client_charges_text'
				WHEN 'pending with a decision' THEN 'client_charges_decided'
				WHEN 'approved without a decision' THEN 'client_charges_decided'
				WHEN 'rejected without a note' THEN 'client_charges_decided'
				WHEN 'cancelled without a note' THEN 'client_charges_cancelled'
				WHEN 'stamp without its actor' THEN 'client_charges_cancelled'
				WHEN 'policy over the cap' THEN 'client_charge_policies_limit'
				WHEN 'policy twice' THEN 'client_charge_policies_tenant_unique'
				WHEN 'unknown line code' THEN 'client_invoice_lines_charge_basis_pair'
				WHEN 'unknown line basis' THEN 'client_invoice_lines_basis_check'
				WHEN 'ad-hoc on the wrong basis' THEN 'client_invoice_lines_charge_basis_pair'
				WHEN 'ad-hoc without a unit' THEN 'client_invoice_lines_uom_basis_pair'
				WHEN 'ad-hoc with a card' THEN 'client_invoice_lines_priced'
				WHEN 'ad-hoc with no rate' THEN 'client_invoice_lines_priced'
				WHEN 'ad-hoc amount not the rounded product' THEN 'client_invoice_lines_priced'
				WHEN 'adjustment with a card' THEN 'client_invoice_lines_priced'
				WHEN 'adjustment amount not its unit' THEN 'client_invoice_lines_priced'
				WHEN 'adjustment over the cap' THEN 'client_invoice_lines_priced'
				WHEN 'adjustment of two' THEN 'client_invoice_lines_extra_kind'
				WHEN 'ad-hoc without its charge' THEN 'client_invoice_lines_extra_kind'
				WHEN 'metered line with a description' THEN 'client_invoice_lines_extra_kind'
				WHEN 'metered line with a charge' THEN 'client_invoice_lines_extra_kind'
				WHEN 'adjustment without a description' THEN 'client_invoice_lines_extra_kind'
				WHEN 'the same charge twice on an invoice' THEN 'client_invoice_lines_line_key_unique'
				WHEN 'metered rate over 1 lakh' THEN 'rate_card_lines_amount_range'
				WHEN 'minimum of zero' THEN 'rate_card_lines_amount_range'
				WHEN 'minimum over 1 crore' THEN 'rate_card_lines_amount_range'
				WHEN 'minimum on the wrong basis' THEN 'rate_card_lines_charge_basis_pair'
				WHEN 'minimum without its counts' THEN 'rate_card_lines_minimum_counts'
				WHEN 'counts on a metered line' THEN 'rate_card_lines_minimum_counts'
				WHEN 'unknown counts' THEN 'rate_card_lines_minimum_counts'
				WHEN 'note line ad-hoc on the wrong basis' THEN 'client_invoice_note_lines_charge_basis'
				ELSE 'client_invoice_note_lines_uom_basis'
			END;
			BEGIN
				CASE probe
					WHEN 'unknown category' THEN UPDATE "client_charges" SET "category" = 'packaging_material' WHERE "id" = ch5;
					WHEN 'labour on the packing SAC' THEN UPDATE "client_charges" SET "category" = 'extra_labour', "sac_code" = '998540' WHERE "id" = ch5;
					WHEN 'other on a goods SAC' THEN UPDATE "client_charges" SET "category" = 'other', "sac_code" = '392310' WHERE "id" = ch5;
					WHEN 'unknown unit' THEN UPDATE "client_charges" SET "unit" = 'litre' WHERE "id" = ch5;
					WHEN 'unknown status' THEN UPDATE "client_charges" SET "status" = 'draft' WHERE "id" = ch5;
					WHEN 'quantity zero' THEN UPDATE "client_charges" SET "quantity_milli" = 0, "amount_paise" = 0 WHERE "id" = ch1;
					WHEN 'rate over the cap' THEN UPDATE "client_charges" SET "unit_rate_paise" = 10000001, "quantity_milli" = 1000, "amount_paise" = 10000001 WHERE "id" = ch1;
					WHEN 'amount over the cap' THEN UPDATE "client_charges" SET "quantity_milli" = 10000000, "unit_rate_paise" = 100001, "amount_paise" = 1000010000 WHERE "id" = ch1;
					WHEN 'amount not the rounded product' THEN UPDATE "client_charges" SET "amount_paise" = 87501 WHERE "id" = ch1;
					WHEN 'bill month not a first' THEN UPDATE "client_charges" SET "bill_month" = '2026-10-02' WHERE "id" = ch1;
					WHEN 'bill month before the service month' THEN UPDATE "client_charges" SET "bill_month" = '2026-09-01' WHERE "id" = ch1;
					WHEN 'malformed gstin' THEN UPDATE "client_charges" SET "supplier_gstin" = 'GSTIN' WHERE "id" = ch1;
					WHEN 'untrimmed description' THEN UPDATE "client_charges" SET "description" = ' padded ' WHERE "id" = ch1;
					WHEN 'description of 201' THEN UPDATE "client_charges" SET "description" = repeat('x', 201) WHERE "id" = ch1;
					WHEN 'reference of 101' THEN UPDATE "client_charges" SET "reference" = repeat('x', 101) WHERE "id" = ch1;
					WHEN 'blank evidence' THEN UPDATE "client_charges" SET "evidence_note" = '' WHERE "id" = ch1;
					WHEN 'pending with a decision' THEN UPDATE "client_charges" SET "decided_by" = u2, "decided_at" = now() WHERE "id" = ch5;
					WHEN 'approved without a decision' THEN UPDATE "client_charges" SET "status" = 'approved' WHERE "id" = ch5;
					WHEN 'rejected without a note' THEN UPDATE "client_charges" SET "status" = 'rejected', "decided_by" = u2, "decided_at" = now() WHERE "id" = ch5;
					WHEN 'cancelled without a note' THEN UPDATE "client_charges" SET "status" = 'cancelled', "cancelled_by" = u1, "cancelled_at" = now() WHERE "id" = ch5;
					WHEN 'stamp without its actor' THEN UPDATE "client_charges" SET "cancelled_by" = NULL WHERE "id" = ch3;
					WHEN 'policy over the cap' THEN
						UPDATE "client_charge_policies" SET "self_approve_limit_paise" = 1000000001 WHERE "tenant_id" = t;
					WHEN 'policy twice' THEN
						INSERT INTO "client_charge_policies" ("id","tenant_id","self_approve_limit_paise","updated_by") VALUES (gen_random_uuid(), t, 0, u1);
					WHEN 'unknown line code' THEN UPDATE "client_invoice_lines" SET "charge_code" = 'packing' WHERE "id" = l_meter;
					WHEN 'unknown line basis' THEN UPDATE "client_invoice_lines" SET "basis" = 'per_carton' WHERE "id" = l_meter;
					WHEN 'ad-hoc on the wrong basis' THEN UPDATE "client_invoice_lines" SET "basis" = 'per_invoice', "uom" = NULL WHERE "id" = l_adhoc;
					WHEN 'ad-hoc without a unit' THEN UPDATE "client_invoice_lines" SET "uom" = NULL WHERE "id" = l_adhoc;
					WHEN 'ad-hoc with a card' THEN UPDATE "client_invoice_lines" SET "rate_card_id" = card WHERE "id" = l_adhoc;
					WHEN 'ad-hoc with no rate' THEN UPDATE "client_invoice_lines" SET "unit_amount_paise" = NULL, "amount_paise" = NULL WHERE "id" = l_adhoc;
					WHEN 'ad-hoc amount not the rounded product' THEN UPDATE "client_invoice_lines" SET "amount_paise" = 5001 WHERE "id" = l_adhoc;
					WHEN 'adjustment with a card' THEN UPDATE "client_invoice_lines" SET "rate_card_id" = card WHERE "id" = l_min;
					WHEN 'adjustment amount not its unit' THEN UPDATE "client_invoice_lines" SET "amount_paise" = 951 WHERE "id" = l_min;
					WHEN 'adjustment over the cap' THEN UPDATE "client_invoice_lines" SET "amount_paise" = 1000000001, "unit_amount_paise" = 1000000001 WHERE "id" = l_min;
					WHEN 'adjustment of two' THEN UPDATE "client_invoice_lines" SET "quantity" = 2 WHERE "id" = l_min;
					WHEN 'ad-hoc without its charge' THEN UPDATE "client_invoice_lines" SET "adhoc_charge_id" = NULL WHERE "id" = l_adhoc;
					WHEN 'metered line with a description' THEN UPDATE "client_invoice_lines" SET "description" = 'Picks' WHERE "id" = l_meter;
					WHEN 'metered line with a charge' THEN UPDATE "client_invoice_lines" SET "adhoc_charge_id" = ch1 WHERE "id" = l_meter;
					WHEN 'adjustment without a description' THEN UPDATE "client_invoice_lines" SET "description" = NULL WHERE "id" = l_min;
					WHEN 'the same charge twice on an invoice' THEN
						INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
								"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise",
								"description","adhoc_charge_id")
							VALUES (gen_random_uuid(), t, inv, NULL, day_from, day_to, 'adhoc', 'per_unit', 'day', 2000, 2500, 5000, '996729', 1800, '29', 'intra', 450, 450, 0,
								'Extra storage — Overflow space', ch6);
					WHEN 'metered rate over 1 lakh' THEN
						UPDATE "rate_card_lines" SET "amount_paise" = 10000001 WHERE "rate_card_id" = card AND "charge_code" = 'pick';
					WHEN 'minimum of zero' THEN
						UPDATE "rate_card_lines" SET "amount_paise" = 0 WHERE "rate_card_id" = card AND "charge_code" = 'minimum_monthly';
					WHEN 'minimum over 1 crore' THEN
						UPDATE "rate_card_lines" SET "amount_paise" = 1000000001 WHERE "rate_card_id" = card AND "charge_code" = 'minimum_monthly';
					WHEN 'minimum on the wrong basis' THEN
						UPDATE "rate_card_lines" SET "basis" = 'per_order' WHERE "rate_card_id" = card AND "charge_code" = 'minimum_monthly';
					WHEN 'minimum without its counts' THEN
						UPDATE "rate_card_lines" SET "minimum_counts" = NULL WHERE "rate_card_id" = card AND "charge_code" = 'minimum_monthly';
					WHEN 'counts on a metered line' THEN
						UPDATE "rate_card_lines" SET "minimum_counts" = 'all' WHERE "rate_card_id" = card AND "charge_code" = 'pick';
					WHEN 'unknown counts' THEN
						UPDATE "rate_card_lines" SET "minimum_counts" = 'adhoc' WHERE "rate_card_id" = card AND "charge_code" = 'minimum_monthly';
					WHEN 'note line ad-hoc on the wrong basis' THEN
						UPDATE "client_invoice_note_lines" SET "basis" = 'per_order', "uom" = NULL WHERE "note_id" = note1;
					WHEN 'note line ad-hoc without a unit' THEN
						UPDATE "client_invoice_note_lines" SET "uom" = NULL WHERE "note_id" = note1;
				END CASE;
			EXCEPTION
				WHEN check_violation OR unique_violation THEN
					GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			END;
			IF refused_by IS DISTINCT FROM expected THEN
				RAISE EXCEPTION 'migration 0099: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
			END IF;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0099', MESSAGE = 'rollback the 0099 probes';
	EXCEPTION
		WHEN SQLSTATE 'P0099' THEN NULL;
	END;

	IF EXISTS (SELECT 1 FROM "client_charges" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_charge_policies" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_invoices" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "rate_cards" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0099: a probe row survived.';
	END IF;
	IF (SELECT count(*) FROM pg_trigger
		WHERE tgname IN ('client_charges_frozen', 'client_invoice_lines_frozen', 'rate_card_lines_frozen', 'client_invoice_note_lines_frozen')
			AND tgenabled = 'O') <> 4 THEN
		RAISE EXCEPTION 'migration 0099: a row trigger is not enabled after the probes.';
	END IF;
	IF EXISTS (SELECT 1 FROM pg_constraint
		WHERE conname IN ('client_invoice_lines_charge_code_check', 'client_invoice_lines_basis_check', 'client_invoice_lines_charge_basis_pair',
			'client_invoice_lines_uom_basis_pair', 'client_invoice_lines_priced', 'client_invoice_lines_extra_kind',
			'rate_card_lines_charge_code_check', 'rate_card_lines_basis_check', 'rate_card_lines_charge_basis_pair', 'rate_card_lines_amount_range',
			'rate_card_lines_minimum_counts', 'client_invoice_note_lines_charge_basis', 'client_invoice_note_lines_uom_basis')
			AND NOT convalidated) THEN
		RAISE EXCEPTION 'migration 0099: a widened CHECK is not validated.';
	END IF;
END $$;
